#!/bin/bash
# Boot the dev server if it isn't up, then capture motion bursts. The lane
# equivalent is generated by lane.sh; canonical had no copy, so bursts could only
# ever be run inside a lane — which is the one place framerate is meaningless.
#   bash tools/burst-run.sh [sequence[,sequence...]]
export PATH=/opt/homebrew/bin:$PATH
cd "$(dirname "$0")/.."
if ! curl -s -o /dev/null http://localhost:5810; then
  nohup npx vite --port 5810 --strictPort --host > /tmp/gauntlet-vite.log 2>&1 &
  for i in $(seq 1 40); do curl -s -o /dev/null http://localhost:5810 && break; sleep 0.5; done
fi
node tools/burst.mjs "$@"
